INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (614, 1, '거부된 파일의 라벨', '`/tmp/audit.log` 는 SELinux 의 AVC 거부 로그입니다. `tcontext=` 는 **대상 파일의 보안 컨텍스트**이고 `사용자:역할:타입:레벨` 로 이뤄집니다. 대상 파일의 **타입**(셋째 칸)을 `/tmp/tcontext.txt` 에 저장하세요. (타입 이름만)', '`tcontext=` 뒤의 값을 콜론으로 쪼개 셋째 칸을 보세요.', 'cat /tmp/audit.log
grep -o ''tcontext=[^ ]*'' /tmp/audit.log | cut -d= -f2 | cut -d: -f3 > /tmp/tcontext.txt
cat /tmp/tcontext.txt

# default_t 는 라벨 규칙이 없는 곳에 새로 만든 파일에 붙는 기본 타입이다. VM 이미지가 virt_image_t 로 라벨돼 있어야 정책이 VM 의 접근을 허용한다(libvirt 는 시작할 때 VM 별 svirt_image_t 로 바꿨다가 끝나면 되돌린다)', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/audit.log <<''EOF''\\ntype=AVC msg=audit(1763629201.123:456): avc:  denied  { read } for  pid=2000 comm=\\"qemu-kvm\\" name=\\"web01.qcow2\\" dev=\\"sda1\\" ino=1000 scontext=system_u:system_r:svirt_t:s0:c100,c200 tcontext=unconfined_u:object_r:default_t:s0 tclass=file permissive=0\\nEOF\\ncat > /tmp/syslog.log <<''EOF''\\nNov 20 09:00:01 host kernel: audit: type=1400 audit(1763629201.123:45): apparmor=\\"DENIED\\" operation=\\"open\\" profile=\\"libvirt-00000000-0000-0000-0000-000000000001\\" name=\\"/data/images/web01.qcow2\\" pid=2000 comm=\\"qemu-system-x86\\" requested_mask=\\"r\\" denied_mask=\\"r\\" fsuid=64055 ouid=0\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/tcontext.txt)\\" = default_t ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "default_t 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/tcontext.txt)\\" = default_t ]"]}]', '[{"title": "libvirt 보안 드라이버", "url": "https://libvirt.org/drvqemu.html#security-driver-selinux"}, {"title": "SELinux 파일 라벨", "url": "https://wiki.centos.org/HowTos/SELinux"}]'),
  (614, 2, 'AppArmor 거부 경로', '`/tmp/syslog.log` 는 AppArmor 의 거부 로그입니다. `name="..."` 에 접근이 막힌 **파일 경로**가 있습니다. 따옴표를 뺀 경로만 `/tmp/denied_path.txt` 에 저장하세요.', '`name=` 뒤 따옴표 안의 값을 뽑으세요. `profile=` 의 값과 헷갈리지 마세요.', 'grep -o ''name="[^"]*"'' /tmp/syslog.log | cut -d''"'' -f2 > /tmp/denied_path.txt
cat /tmp/denied_path.txt

# Ubuntu 계열은 SELinux 대신 AppArmor 를 쓴다. libvirt 가 VM 마다 profile=libvirt-UUID 프로파일을 만들고 허용 경로는 디스크 목록에서 자동으로 넣는다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/audit.log <<''EOF''\\ntype=AVC msg=audit(1763629201.123:456): avc:  denied  { read } for  pid=2000 comm=\\"qemu-kvm\\" name=\\"web01.qcow2\\" dev=\\"sda1\\" ino=1000 scontext=system_u:system_r:svirt_t:s0:c100,c200 tcontext=unconfined_u:object_r:default_t:s0 tclass=file permissive=0\\nEOF\\ncat > /tmp/syslog.log <<''EOF''\\nNov 20 09:00:01 host kernel: audit: type=1400 audit(1763629201.123:45): apparmor=\\"DENIED\\" operation=\\"open\\" profile=\\"libvirt-00000000-0000-0000-0000-000000000001\\" name=\\"/data/images/web01.qcow2\\" pid=2000 comm=\\"qemu-system-x86\\" requested_mask=\\"r\\" denied_mask=\\"r\\" fsuid=64055 ouid=0\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/denied_path.txt)\\" = /data/images/web01.qcow2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "경로다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/denied_path.txt)\\" = /data/images/web01.qcow2 ]"]}]', '[{"title": "libvirt 보안 드라이버", "url": "https://libvirt.org/drvqemu.html#security-driver-selinux"}, {"title": "SELinux 파일 라벨", "url": "https://wiki.centos.org/HowTos/SELinux"}]'),
  (614, 3, '라벨 규칙 등록과 복원', '`/data/images` 아래 파일이 모두 `virt_image_t` 타입을 갖도록 **라벨 규칙을 등록하고(`semanage fcontext`) 그 규칙대로 라벨을 다시 입히는(`restorecon`)** 명령 두 줄을 `/tmp/fix.txt` 에 순서대로 적으세요. (실행하지 않습니다)', '규칙 등록이 먼저이고, 복원은 하위 디렉터리까지 재귀로 합니다. 경로 패턴은 `(/.*)?` 로 끝납니다.', 'printf ''%s\\n'' "semanage fcontext -a -t virt_image_t ''/data/images(/.*)?''" ''restorecon -Rv /data/images'' > /tmp/fix.txt
cat /tmp/fix.txt

# chcon 으로 바꾸면 재라벨링 때 되돌아간다. semanage 로 규칙을 등록해야 영구 반영된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/audit.log <<''EOF''\\ntype=AVC msg=audit(1763629201.123:456): avc:  denied  { read } for  pid=2000 comm=\\"qemu-kvm\\" name=\\"web01.qcow2\\" dev=\\"sda1\\" ino=1000 scontext=system_u:system_r:svirt_t:s0:c100,c200 tcontext=unconfined_u:object_r:default_t:s0 tclass=file permissive=0\\nEOF\\ncat > /tmp/syslog.log <<''EOF''\\nNov 20 09:00:01 host kernel: audit: type=1400 audit(1763629201.123:45): apparmor=\\"DENIED\\" operation=\\"open\\" profile=\\"libvirt-00000000-0000-0000-0000-000000000001\\" name=\\"/data/images/web01.qcow2\\" pid=2000 comm=\\"qemu-system-x86\\" requested_mask=\\"r\\" denied_mask=\\"r\\" fsuid=64055 ouid=0\\nEOF\\ntrue"]', '["sh", "-c", "( grep -E \\"semanage[[:space:]]+fcontext\\" /tmp/fix.txt | grep -Eq -- \\"(-a|--add|-m|--modify)([[:space:]]|$)\\" && grep -E \\"semanage[[:space:]]+fcontext\\" /tmp/fix.txt | grep -Eq -- \\"-t[[:space:]]+virt_image_t([[:space:]]|$)\\" && grep -E \\"semanage[[:space:]]+fcontext\\" /tmp/fix.txt | grep -Fq \\"/data/images(/.*)?\\" ) && ( grep -E \\"restorecon\\" /tmp/fix.txt | grep -Eq -- \\"-[A-Za-z]*[Rr]|--recursive\\" && grep -E \\"restorecon\\" /tmp/fix.txt | grep -q \\"/data/images\\" ) && ( [ \\"$(grep -n semanage /tmp/fix.txt | head -1 | cut -d: -f1)\\" -lt \\"$(grep -n restorecon /tmp/fix.txt | head -1 | cut -d: -f1)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "semanage 로 virt_image_t 규칙을 등록한다", "cmd": ["sh", "-c", "grep -E \\"semanage[[:space:]]+fcontext\\" /tmp/fix.txt | grep -Eq -- \\"(-a|--add|-m|--modify)([[:space:]]|$)\\" && grep -E \\"semanage[[:space:]]+fcontext\\" /tmp/fix.txt | grep -Eq -- \\"-t[[:space:]]+virt_image_t([[:space:]]|$)\\" && grep -E \\"semanage[[:space:]]+fcontext\\" /tmp/fix.txt | grep -Fq \\"/data/images(/.*)?\\""]}, {"label": "restorecon 을 재귀로 쓴다", "cmd": ["sh", "-c", "grep -E \\"restorecon\\" /tmp/fix.txt | grep -Eq -- \\"-[A-Za-z]*[Rr]|--recursive\\" && grep -E \\"restorecon\\" /tmp/fix.txt | grep -q \\"/data/images\\""]}, {"label": "규칙 등록이 복원보다 앞이다", "cmd": ["sh", "-c", "[ \\"$(grep -n semanage /tmp/fix.txt | head -1 | cut -d: -f1)\\" -lt \\"$(grep -n restorecon /tmp/fix.txt | head -1 | cut -d: -f1)\\" ]"]}]', '[{"title": "libvirt 보안 드라이버", "url": "https://libvirt.org/drvqemu.html#security-driver-selinux"}, {"title": "SELinux 파일 라벨", "url": "https://wiki.centos.org/HowTos/SELinux"}]'),
  (614, 4, 'sVirt 의 목적', 'sVirt 가 VM 프로세스마다 서로 다른 SELinux 카테고리(`c100,c200` 같은 값)를 붙이는 목적은?', '한 VM 이 침해돼도 다른 VM 의 자원은 보호돼야 합니다.', NULL, NULL, '[]', 'choice', '["VM 들의 CPU 사용 시간을 서로 공정하게 나눠 준다", "VM 이 쓰는 네트워크 속도를 조금 더 높여 준다", "한 VM 의 QEMU 가 다른 VM 의 이미지에 접근하지 못하게 격리한다", "VM 이미지를 압축해 디스크 사용 용량을 줄여 준다"]', 2, 'sVirt 는 VM 시작 때 프로세스와 이미지에 같은 고유 MCS 카테고리를 붙여 같은 쌍끼리만 접근하게 합니다. 파일 권한이 같아도 다른 VM 의 이미지에는 접근할 수 없습니다.', NULL, NULL, NULL, NULL),
  (614, 5, '권한이 맞는데 거부될 때', '이미지 파일의 소유자·모드가 올바른데도 qemu 로그에 Permission denied 가 납니다. 가장 먼저 의심할 것은?', '파일 모드(chmod) 말고 파일에 붙은 또 다른 속성을 보세요.', NULL, NULL, '[]', 'choice', '["서버의 시계가 몇 분 틀어졌는지 여부", "파일의 SELinux 라벨(`ls -Z`)과 거부 로그", "게스트 OS 가 바이러스에 감염됐는지 여부", "이미지 파일 이름이 몇 글자인지 여부"]', 1, '리눅스 권한(DAC)이 맞아도 SELinux·AppArmor(MAC)가 별도로 거부할 수 있습니다. ls -Z 로 라벨을 보고 audit.log 의 AVC 나 syslog 의 apparmor DENIED 를 확인합니다.', NULL, NULL, NULL, NULL),
  (614, 6, '해결 방법', 'SELinux 거부로 VM 이 시작되지 않을 때 가장 바른 해결은?', '정책을 끄면 다른 VM 의 격리도 함께 사라집니다.', NULL, NULL, '[]', 'choice', '["잘못된 라벨 규칙을 바로잡고 파일에 복원한다", "`setenforce 0` 으로 SELinux 를 끄고 계속 운영한다", "qemu.conf 에서 보안 드라이버를 none 으로 영구 설정한다", "이미지 파일 권한을 모두에게 777 로 열어 둔다"]', 0, '원인인 잘못된 라벨만 고치는 것이 정답입니다. setenforce 0 은 일시적 진단용일 뿐이고, 운영에서 끄거나 none 으로 두거나 777 로 여는 것은 VM 간 격리를 포기하는 것입니다.', NULL, NULL, NULL, NULL),
  (614, 7, '라벨 보기', '파일의 SELinux 라벨을 함께 보여 주는 `ls` 옵션을 채우세요. (대소문자 구분)', '대문자 한 글자입니다.', NULL, NULL, '[]', 'fill', '["Z", "l", "a", "i"]', NULL, '`ls -Z` 는 SELinux 보안 컨텍스트를 함께 출력합니다. `-l` 은 상세 목록, `-a` 는 숨김 포함, `-i` 는 inode 번호입니다.', '[0]', 'ls -{0} /data/images', NULL, NULL),
  (614, 8, '권한 거부 대응', 'VM 이 "Permission denied" 로 시작하지 못합니다. 보안 정책 거부로 확인됐을 때의 올바른 대응 순서로 놓으세요.', '각 단계는 앞 단계의 결과를 근거로 합니다.', NULL, NULL, '[]', 'order', '["VM 을 다시 시작해 본다", "파일의 라벨을 규칙대로 복원한다", "라벨 규칙을 등록한다", "거부 로그로 파일과 라벨을 확인한다"]', NULL, '먼저 로그로 거부된 파일과 라벨을 확인하고, 올바른 규칙을 등록한 뒤 복원해 적용하고, 마지막에 VM 을 다시 시작합니다.', '[3, 2, 1, 0]', NULL, NULL, NULL);
